"""The exe's version resource and manifest (report item K8), generated by scripts/windows_resources.py."""

import importlib.util
import xml.etree.ElementTree as ET
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent


def _resources():
    spec = importlib.util.spec_from_file_location("windows_resources", ROOT / "scripts" / "windows_resources.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.mark.parametrize("text, expected", [
    ("0.3.1", (0, 3, 1, 0)),
    ("1.2", (1, 2, 0, 0)),
    ("2.0.1rc1", (2, 0, 1, 1)),
    ("dev", (0, 0, 0, 0)),
    ("70000.1", (65535, 1, 0, 0)),
])
def test_version_tuple_has_four_16_bit_numbers(text, expected):
    assert _resources().version_tuple(text) == expected


def test_the_version_comes_from_the_stamped_file_or_is_dev(tmp_path):
    res = _resources()
    stamped = tmp_path / "_version.py"
    stamped.write_text('__version__ = "0.4.2"\n', encoding="utf-8")
    assert res.app_version(str(stamped)) == "0.4.2"
    assert res.app_version(str(tmp_path / "missing.py")) == "dev"


def test_the_version_file_names_the_one_publisher_and_parses_in_pyinstaller(tmp_path):
    res = _resources()
    path = res.write_version_file(str(tmp_path), "0.4.2")
    text = Path(path).read_text(encoding="utf-8")
    assert 'StringStruct(u"CompanyName", u"MELEJ")' in text
    assert 'StringStruct(u"ProductVersion", u"0.4.2")' in text
    assert "filevers=(0, 4, 2, 0)" in text
    versioninfo = pytest.importorskip("PyInstaller.utils.win32.versioninfo")
    assert versioninfo.load_version_info_from_text_file(path).ffi.fileVersionMS == (0 << 16) | 4
    dev = Path(res.write_version_file(str(tmp_path / "dev"), "dev")).read_text(encoding="utf-8")
    assert 'u"0.0.0 (dev)"' in dev


def test_the_manifest_sets_a_utf8_code_page_and_per_monitor_dpi(tmp_path):
    root = ET.parse(_resources().write_manifest(str(tmp_path))).getroot()
    values = {el.tag.split("}")[1]: el.text for el in root.iter() if el.text and el.text.strip()}
    assert values["activeCodePage"] == "UTF-8"
    assert values["dpiAwareness"] == "PerMonitorV2"
    assert values["longPathAware"] == "true"


def test_the_spec_embeds_both():
    spec = (ROOT / "PixelFlow.spec").read_text(encoding="utf-8")
    assert "version=VERSION_PATH" in spec and "manifest=MANIFEST_PATH" in spec
